package br.com.gestao.sale; import br.com.gestao.sale.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/sales") public class SaleController{private final SaleService service;public SaleController(SaleService s){service=s;} @GetMapping public List<Sale> list(Authentication a){boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));return service.list(a.getName(),admin);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Sale create(@Valid @RequestBody CreateSaleRequest q,Authentication a){return service.create(q,a.getName());}}